```rust
struct Employee {
    rate: f64,
    has_special_skill: bool,
    ssn: String,
    address: String,
    // ... many unrelated fields
}
struct Timesheet;
impl Timesheet {
    fn charge(&self, emp: &Employee, days: u32) -> f64 {
        let base = emp.rate * days as f64;
        if emp.has_special_skill {
            base * 1.05
        } else {
            base
        }
    }
}
```

fix:
Define a narrow trait containing only the required properties and make the method accept that trait.
```rust
trait Billable {
    fn rate(&self) -> f64;
    fn has_special_skill(&self) -> bool;
}
impl Timesheet {
    fn charge(&self, emp: &impl Billable, days: u32) -> f64 {
        let base = emp.rate() * days as f64;
        if emp.has_special_skill() { base * 1.05 } else { base }
    }
}
```
